def translate_with_gemini(api_key, text, lang, target_lang, model="gemini-1.5-flash"):
    import urllib.request
    import urllib.parse
    
    url = f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent?key={api_key}"
    target_name = "natural English" if target_lang == "en" else "natural Russian"
    prompt = (
        f"You are a professional manga/manhwa/manhua translator. "
        f"Translate the following raw dialogue line from {lang} into {target_name}. "
        f"Preserve conversational nuance, slang, honorifics (if appropriate), and emotional tone. "
        f"Output ONLY the translated line without any comments or quotes.\n\n"
        f"Dialogue: {text}"
    )
    payload = {
        "contents": [{"parts": [{"text": prompt}]}],
        "generationConfig": {"temperature": 0.2, "maxOutputTokens": 200}
    }
    req = urllib.request.Request(
        url,
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json"}
    )
    with urllib.request.urlopen(req) as resp:
        res = json.loads(resp.read().decode("utf-8"))
        return res["candidates"][0]["content"]["parts"][0]["text"].strip()

def main():
    parser = argparse.ArgumentParser(description="Generate or build silver reference translations")
    parser.add_argument("--api-key", default=os.getenv("GEMINI_API_KEY"), help="Gemini API Key (optional)")
    parser.add_argument("--model", default="gemini-1.5-flash", help="Gemini model name")
    parser.add_argument("--input", default="tools/mt-eval/data/eval_dataset.json", help="Input dataset path")
    parser.add_argument("--output", default="tools/mt-eval/data/silver_references.json", help="Output path")
    parser.add_argument("--refresh-online", action="store_true", help="Force refresh online using Gemini API")
    args = parser.parse_args()

    input_path = Path(args.input)
    output_path = Path(args.output)
    output_path.parent.mkdir(parents=True, exist_ok=True)

    with open(input_path, "r", encoding="utf-8") as f:
        dataset = json.load(f)

    print(f"Building silver references for {len(dataset)} items...")
    references = build_default_silver_references(dataset)

    if args.refresh_online:
        if not args.api_key:
            print("ERROR: --refresh-online requires --api-key or GEMINI_API_KEY environment variable.")
            sys.exit(1)
        print(f"Querying Gemini API ({args.model}) to translate dialogue...")
        for item in dataset:
            idx = item["id"]
            lang = item["lang"]
            text = item["ocr_text"]
            try:
                en = translate_with_gemini(args.api_key, text, lang, "en", args.model)
                time.sleep(0.5)
                ru = translate_with_gemini(args.api_key, text, lang, "ru", args.model)
                time.sleep(0.5)
                references[idx]["silver_en"] = en
                references[idx]["silver_ru"] = ru
                print(f"[{idx}] Gemini -> EN: {en} | RU: {ru}")
            except Exception as e:
                print(f"[{idx}] Gemini API failed ({e}), keeping pre-computed silver reference.")

    output_list = list(references.values())
    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(output_list, f, ensure_ascii=False, indent=2)

    print(f"Saved {len(output_list)} silver references to {output_path}")

if __name__ == "__main__":
    main()
